import { useContext } from "react";
import { AppContext } from "../context/AppContext";

export default function Header() {
  const { role, username, setRole } = useContext(AppContext);

  return (
    <header>
      <div className="brand">
        <div className="logo-circle">DC</div>
        <div>
          <h1>Digital Canteen</h1>
          <span>Smart Canteen Management System</span>
        </div>
      </div>

      <div className="header-actions">
        <span className="tag-pill">
          {role ? `Logged in as ${role === "admin" ? "Admin" : username}` : "Not logged in"}
        </span>

        {role && (
          <button
  className="btn btn-outline btn-sm"
  onClick={() => {
    localStorage.clear();
    setRole(null);
  }}
>
  Logout
</button>

        )}
      </div>
    </header>
  );
}
